import "core-js/modules/es6.number.constructor";
export default {
  props: {
    placeholder: {
      type: String
    },
    treeData: {
      type: Array,
      default: []
    },
    disabled: {
      type: Boolean,
      default: false
    },
    formValue: {
      type: String,
      default: ''
    },
    defaultProps: {
      type: Object,
      default: {
        label: 'fullName',
        value: 'id',
        leaf: 'hasChildren',
        disabled: 'disabled'
      }
    },
    selectType: {
      type: String,
      default: ''
    },
    userUnit: {
      type: String,
      default: ''
    },
    formIndex: {
      type: Number,
      default: -1
    }
  },
  data: function data() {
    return {
      showTree: false,
      treeList: this.$store.state.user.userUnitList,
      treeItems: []
    };
  },
  watch: {
    showTree: function showTree(val) {
      if (val) {
        document.body.addEventListener('click', this.watchContextmenu);
      } else {
        document.body.removeEventListener('click', this.watchContextmenu);
      }
    },
    userUnit: function userUnit(val) {
      if (val != '' && val != null) {
        //如果是部门下拉框且，组件传入了单位，则加载用户单位下部门 并隐藏班组
        if (this.selectType == 'DEPT') {
          var arrs = this.loadDeptList(this.treeList, this.userUnit);
          // console.log(arrs)
          this.treeItems = arrs;
        }
      }
    }
  },
  mounted: function mounted() {
    //防止删除更改原有数组
    this.treeItems = JSON.parse(JSON.stringify(this.treeList));
  },
  methods: {
    //加载单位下部门
    loadDeptList: function loadDeptList(list, unitName) {
      var arrs = null;
      for (var i = 0; i < list.length; i++) {
        var item = list[i];
        if (item.children && item.children.length > 0) {
          var temps = this.loadDeptList(item.children, unitName);
          if (temps && temps.length > 0) {
            return temps;
          }
        }
        if (item.fullName === unitName) {
          arrs = item.children;
        }
      }
      return arrs;
    },
    //加载单位
    // loadCorpList(list) {
    //   for (let i = list.length - 1; i >= 0; i--) {
    //     if (list[i].type == 'DEPT') {
    //       list.splice(i, 1)
    //     }
    //     if (list[i] && list[i].children) this.loadCorpList(list[i].children)
    //   }
    // },
    filterNodeMethod: function filterNodeMethod(value, data, node) {
      if (data.type == this.selectType) return true;
      return false;
    },
    nodeExpand: function nodeExpand(data, node, dom) {
      //create筛选
      this.$refs.tree.filter(this.selectType);
    },
    watchContextmenu: function watchContextmenu(e) {
      this.showTree = false;
    },
    handlePopver: function handlePopver() {
      if (this.disabled) return;
      this.showTree = !this.showTree;
    },
    nodeClick: function nodeClick(data, node) {
      if (this.selectType == data.type) {
        this.$emit("getTreeItem", data, this.formIndex);
        this.showTree = false;
      } else {
        if (this.selectType == 'CORP') {
          this.$message({
            type: "warning",
            message: "请选择单位类型!"
          });
        } else {
          this.$message({
            type: "warning",
            message: "请选择部门类型!"
          });
        }
      }
    }
  }
};
